import math

def interp(points, x):
    pts = sorted((p[0], p[1]) for p in points)
    for i in range(len(pts)-1):
        a,b=pts[i],pts[i+1]
        if a[0] <= x <= b[0] and b[0]-a[0]>0.01:
            return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
    return None

def control(obs):
    m=obs['local_map']
    left=m['left_rail']; right=m['right_rail']
    look=5.0
    l=interp(left,look); r=interp(right,look)
    if l is None or r is None:
        look=3.0
        l=interp(left,look); r=interp(right,look)
    centre=(l+r)/2 if l is not None and r is not None else 0.0
    desired=max(-18.0,min(18.0, -math.degrees(math.atan2(centre,look))*0.8))
    hitch=obs['hitch_deg']
    steer=max(-40.0,min(40.0, 2.1*(hitch-desired)))
    speed=-0.75 if abs(hitch)<25 else -0.4
    return (steer,speed,180)

